import{z as n,x as A,o as r,c as p,q as s,j as B,D as t,d as e,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"优先级继承与天花板","description":"","frontmatter":{"title":"优先级继承与天花板","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pi-pcp.md","filePath":"cs/pi-pcp.md","lastUpdated":1791063341000}'),d={name:"cs/pi-pcp.md"};function P(m,a,C,c,D,u){const o=A("Mermaid");return r(),p("div",null,[a[2]||(a[2]=s('<h1 id="优先级继承与天花板" tabindex="-1">优先级继承与天花板 <a class="header-anchor" href="#优先级继承与天花板" aria-label="Permalink to &quot;优先级继承与天花板&quot;">​</a></h1><div class="epigraph"><p>持锁者临时继承等待者中的最高优先级，或锁事先抬到可能碰它的任务的天花板，于是中优先级不能插在临界区中间。</p><footer>—— 据 Sha, Rajkumar and Lehoczky, Priority Inheritance Protocols, IEEE TC 1990；Liu and Layland 实时环境整理</footer></div><p><a href="/cs/priority-inversion">上一课</a>给出无界反转。缺口是两条经典协议：<strong>优先级继承（PI）</strong>——持锁者优先级 = max(自身, 等待者)；<strong>优先级天花板（PCP）</strong>——任务拿锁时抬到该锁的静态天花板。本课钉有界等待的直觉，不把所有嵌套锁的证明写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只靠「别用锁」在内核里做不到。PI： \\(H\\) 等 \\(L\\) 的锁，则 \\(L\\) 以 \\(H\\) 的优先级跑完临界区，\\(M\\) 插不进去；放锁后 \\(L\\) 回落。链式等待会把优先级沿等待链传播。PCP：每把锁有天花板 = 可能锁定它的任务的最高优先级；持锁即升到天花板，于是能碰这把锁的人之间互斥更粗、分析更易。缺口不是再画三线程时间线，而是这两条抬升规则。</p><p><span class="marginnote">直觉类比：PI 就是让挡路的事故车临时挂上急救灯——只要急救车在等它，它就按急救车的优先级清路；放锁后立刻摘灯，回到普通身份。</span></p><p><span class="marginnote">自阻塞：PCP 下任务可能在锁空闲时仍因天花板规则被挡住，换来死锁避免与更简单的最坏时间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现 PI：锁上记录持有者与等待队列；阻塞时比较并 boost 持有者，必要时再 boost 它正在等的人。调度器看见的是 boost 后的优先级。PCP：静态分析或声明每锁天花板；获取时升、释放时降到仍持有的锁的最大天花板。本课不绑定 Linux <code>rt_mutex</code> 的字段名。</p>',9)),(r(),B(l,null,{default:t(()=>[i(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E7%AD%89%E9%94%81%22%5D%20--%3E%20BOOST%5B%22%E6%8A%AC%E5%8D%87%E6%8C%81%E6%9C%89%E8%80%85%22%5D%0A%20%20BOOST%20--%3E%20L%5B%22%E6%8C%81%E6%9C%89%E8%80%85%E4%BB%A5%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%E8%B7%91%E5%AE%8C%E4%B8%B4%E7%95%8C%E5%8C%BA%22%5D%0A%20%20L%20--%3E%20REL%5B%22%E6%94%BE%E9%94%81%E5%B9%B6%E5%9B%9E%E8%90%BD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[e("与"),E("a",{href:"/cs/mlfq"},"MLFQ"),e(" 的档位：boost 必须立刻生效，不能等反馈降档周期。")],-1)),a[4]||(a[4]=E("p",null,[E("span",{class:"marginnote"},"数字实例：一把锁被优先级 1（最高）、3、5 三种任务用过，它的天花板就是 1；任何任务一拿到它，立刻按 1 级跑——哪怕此刻只有优先级 9 的任务在等。天花板是静态算好的，不看现场。")],-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,"PI 让锁上的依赖变成调度器暂时承认的优先级，反转等待被收成临界区长度（再加链上其他人的临界区）。它不消灭死锁：循环等锁仍循环。PCP 的天花板若设对，某些死锁配置进不去，那是副作用，不是银行家。实时课的 WCET 要把 boost 进来的干扰算进去。",-1)),(r(),B(l,null,{default:t(()=>[i(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20PIP%5B%22%E4%BC%98%E5%85%88%E7%BA%A7%E7%BB%A7%E6%89%BF%20PI%22%5D%0A%20%20%20%20A1%5B%22%E6%8A%AC%E5%8D%87%E9%87%8F%3A%20%E7%AD%89%E5%BE%85%E8%80%85%E4%B8%AD%E7%9A%84%E6%9C%80%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%22%5D%20--%3E%20A2%5B%22%E5%8A%A8%E6%80%81%3A%20%E8%B0%81%E7%AD%89%E5%B0%B1%E7%BB%A7%E6%89%BF%E8%B0%81%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E6%AD%BB%E9%94%81%E4%BB%8D%E5%8F%AF%E8%83%BD%2C%20%E9%93%BE%E5%BC%8F%E4%BC%A0%E6%92%AD%E8%A6%81%E5%AE%9E%E7%8E%B0%E5%A5%BD%22%5D%0A%20%20end%0A%20%20subgraph%20PCPS%5B%22%E4%BC%98%E5%85%88%E7%BA%A7%E5%A4%A9%E8%8A%B1%E6%9D%BF%20PCP%22%5D%0A%20%20%20%20B1%5B%22%E6%8A%AC%E5%8D%87%E9%87%8F%3A%20%E9%94%81%E7%9A%84%E9%9D%99%E6%80%81%E5%A4%A9%E8%8A%B1%E6%9D%BF%22%5D%20--%3E%20B2%5B%22%E4%B8%80%E6%8B%BF%E5%88%B0%E9%94%81%E5%B0%B1%E5%88%B0%E9%A1%B6%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E5%8F%AF%E9%81%BF%E5%85%8D%E6%AD%BB%E9%94%81%2C%20%E6%9C%80%E5%9D%8F%E6%97%B6%E9%97%B4%E5%A5%BD%E5%88%86%E6%9E%90%22%5D%0A%20%20end%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 POSIX <code>PTHREAD_PRIO_INHERIT</code> 的全部失败模式写完，不讨论如何在用户 futex 上做 PI（后课 futex 会点名）。公平分时默认不用 PI；它是优先级调度的配件。</p><p><span class="marginnote">常见误区：以为上了优先级继承就不会死锁——PI 只管「谁先跑」，不管「谁等谁」；A 持锁 1 等锁 2、B 持锁 2 等锁 1，照样互相卡死。PCP 的防死锁是有前提的设计副作用，不是万灵药。</span></p><p>后课默认：有优先级就应想到 PI/PCP。通用分时若改用权重摊时间而不是固定档，下一课从<a href="/cs/timeslice-cfs">时间片与公平调度</a>已经给出的直觉往下拆 vruntime。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PI：持锁者继承等待者优先级；PCP：按锁的天花板抬升。</li><li>反转等待可有界；死锁不因此消失。</li><li>权重公平与虚拟时间是 CFS 课序的下一缺口。</li><li>出处：Sha, Rajkumar, Lehoczky, <em>IEEE TC</em> 1990；Silberschatz et al., <em>OSC</em>。</li></ul>',6))])}const _=n(d,[["render",P]]);export{f as __pageData,_ as default};
